INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(33100, 0, 331, 0, 0, 0, 'Ashenvale', 'Ashenvale is the great forest of the night elves, a land of towering ancient trees south of Darkshore and Felwood, reaching down to the Barrens and the Stonetalon Mountains. After the Sundering the kaldorei rebuilt their society beneath its boughs, and for long ages the Sentinels patrolled its shadows while the druids slept. The Third War broke that peace. Grom Hellscream''s Warsong orcs came to the forest, clashed with the Sentinels, and in a rage not wholly their own slew the demigod Cenarius. Grom later redeemed his honor by helping Thrall destroy the pit lord Mannoroth. The Warsong still cut the forest''s timber, and the Silverwing Sentinels fight the Warsong Outriders for every grove. The Alliance holds Astranaar and Maestra''s Post, while the Horde holds Splintertree Post and Zoram''gar on the coast. Around them the furbolg tribes have turned savage, satyrs haunt old ruins, naga swarm the Zoram Strand, the Forsaken defile a barrow den, and remnants of the Burning Legion linger in the east.', 'warcraft.wiki.gg/wiki/Ashenvale (geography, kaldorei history, Third War); page_text 1844 (night elves expand into the forest they called Ashenvale), 1851 (Sentinels patrol Ashenvale), 2077-2078 (Hellscream kills Cenarius, later helps Thrall defeat Mannoroth); quest 8372 description (Silverwing Sentinels at war with the Warsong Outriders); quests 9533, 9428, 6543, 1008, 1011, 9516'),
(33101, 1, 331, 1, 0, 0, 'Maestra''s Post', 'Maestra''s Post is a small night elf camp of a tower and a large hall on the road through western Ashenvale, and an unusual meeting place. Two humans live here: the paladin Delgren the Purifier, who helps the Sentinels wherever demons or undead are found, and Feero Ironhand, who carries Delgren''s supplies and messages north to Auberdine, though cult assassins and undead lurk along the road. The herbalist Orendil Broadleaf brews his remedies here. Liladris Moonriver waits for the drowsy druid Kerlonian Evershade to find his way down from Darkshore, and Sentinel Onaeya awaits word of Aynasha, a Sentinel sent toward Auberdine whom furbolg trackers ambushed and poisoned on the way.', 'warcraft.wiki.gg/wiki/Maestra''s_Post (tower and large building, Delgren and Feero the only humans); quest 967 reward text, quest 976 description; creature_text 4484 (Feero: assassins from the cult, undead); quests 1010, 5321, 5713; zone_areas: Delgren 3663, Feero 4484, Orendil 3847, Liladris 11219, Onaeya 11806 in area 413; warcraft.wiki.gg/wiki/Maestra''s_Post (tower and a large night elven building)'),
(33102, 1, 331, 2, 0, 0, 'Ordil''Aran and Bathran''s Haunt', 'North of Maestra''s Post, toward the Darkshore border, two old ruins stand in the woods. At the Ruins of Ordil''Aran the warlocks of the Cult of the Dark Strand have made camp. Cultists, adepts and a frenzied enforcer guard excavators who dig among the stones, and one of them is said to carry a soul gem holding the secret of the cult''s power. A little farther north lies Bathran''s Haunt, where a plant called Bathran''s Hair once grew, known for curing ailments of the spirit. The Forsaken now prowl those ruins, seekers, herbalists and thugs moving among the stones, and the night elves find their presence deeply troubling.', 'quest 970 description (Dark Strand at Ordil''Aran, northeast of Maestra''s Post, soul gem); quest 1010 description and reward text (Bathran''s Hair, north of Maestra''s Post, Forsaken there are troubling); zone_areas: Dark Strand Cultist, Excavator, Adept, Enforcer in 412; Forsaken Seeker, Herbalist, Thug and Apothecary Falthis in 411; creature_text 3727 (enforcer frenzy)'),
(33103, 1, 331, 3, 0, 0, 'The Zoram Strand', 'The Zoram Strand is the long northwestern shore of Ashenvale. Beneath its waves lies Zoram, a night elf city destroyed in the Sundering and swallowed by the sea, lost and nearly forgotten for ages. Now the naga have returned to it, for reasons no one knows. Wrathtail myrmidons, sorceresses, sea witches and wave riders crowd the beaches among crawlers and hydras, a naga called Lady Vespia is sometimes seen among them, and their leader Ruuzel keeps an isle on the northern edge of the drowned city. Offshore the naga keep a brazier burning in honor of the hydra Vorsha. North of Zoram''gar, Fallenroot satyrs and tide priestesses watch over the entrance to Blackfathom Deeps.', 'warcraft.wiki.gg/wiki/Zoram_Strand (city of Zoram, naga, BFD entrance); quest 1008 description (Zoram destroyed in the Sundering, naga returned); quest 1009 description (Ruuzel''s isle on the northern edge of Zoram); quest 6641 description (naga brazier honoring Vorsha); quest 6563 description (BFD north of Zoram''gar); zone_areas area 414: Wrathtail naga, crawlers, Mystlash Hydra, Lady Vespia 10559, Ruuzel 3943, Fallenroot Satyr, Blackfathom Tide Priestess, Naga Brazier'),
(33104, 1, 331, 4, 0, 0, 'Zoram''gar Outpost', 'Zoram''gar Outpost is the Horde''s foothold on the western coast of Ashenvale, a camp of orcs and Darkspear trolls on the Zoram Strand. Karang Amakkar calls it the front line of the Horde''s conquest of the forest and sends fighters against the furbolgs who stand between this coast and Splintertree Post. Naga raids are frequent, and the hydra Vorsha the Lasher has struck the camp again and again without provocation, until Muglash resolved to draw her out by putting out the naga''s brazier. Marukai wants the naga thrown back into the depths, the troll Mitsuwa grieves for kin killed by Thistlefur furbolgs on their way here, and Je''neu Sancrea of the Earthen Ring studies the waters and the deeps nearby.', 'warcraft.wiki.gg/wiki/Zoram''gar_Outpost (orcs and jungle trolls); creature_template faction 126 (Darkspear) for Marukai, Mitsuwa, Je''neu; gossip Karang Amakkar 12757 (front lines in our conquest of Ashenvale); quests 216, 6442, 6462, 6641, 6545 (Warsong Runner: naga attacks on the outpost); zone_areas area 2897'),
(33105, 1, 331, 5, 0, 0, 'Thistlefur Village', 'North of Astranaar and east of the Zoram Strand lies Thistlefur Village, home of the Thistlefur furbolgs, who outnumber even the fierce Foulweald. The furbolgs were not always enemies of the night elves, but the Thistlefur have grown corrupt and savage, and their numbers have swelled so fast that Raene Wolfrunner fears they may soon dare to attack Astranaar itself. Their chieftain is Dal Bloodclaw, and the brute Rorgish Jowl prowls among them. At the far end of the village is Thistlefur Hold, a cave where the tribe keeps its plunder, including sacred charms taken from slain trolls. The Thistlefur even caged Ruul Snowhoof here, having mistaken him for a bear.', 'quest 1054 description (Thistlefur north of Astranaar, numbers grown, chieftain''s skull); quest 216 description (east of Zoram Strand); quest 6621 description (Foulweald not as many as the Thistlefur); quest 1025 request text (furbolg were not always our enemy); quest 6462 description (troll charms in Thistlefur Hold, a cave at the end of the village); quest 6482 description and reward text; zone_areas area 2301: Dal Bloodclaw 3987, Rorgish Jowl 10639, Ruul Snowhoof 12818 and cage'),
(33106, 1, 331, 6, 0, 0, 'Astranaar', 'Astranaar is the chief night elf town of Ashenvale, built on an island in a lake and joined to the shore by bridges where the main road passes through. Travelers find an inn, a hippogryph roost and a shelf of old histories. Raene Wolfrunner and her wolf Dagri direct the struggle against the furbolgs, while Shindrell Swiftfire sends fighters against the naga of the Zoram Strand and reports to Kayneth Stillwind at Forest Song. Faldreas Goeth''Shael listens to the forest spirits, and Sentinel Thenysil frets over a friend sent to Stonetalon. In one house, Pelturas Whitemoon keeps watch over his gravely ill daughter.', 'warcraft.wiki.gg/wiki/Astranaar (island in a lake, bridges, largest settlement); gossip Shindrell Swiftfire 3845 (exposed given the Horde buildup to the south); gossip Vindicator Palanaar 17106; quest 9533 (Palanaar is female); quests 1008, 1056, 1070, 1020; zone_areas area 415: Astranaar Sentinels, Daelyshia, Innkeeper Kimlya, Dagri, books 175724, 175726, 175756, 175757; quest 4581 (Shindrell''s report to Kayneth)'),
(33107, 1, 331, 7, 0, 0, 'The Shrine of Aessina', 'In the woods of western Ashenvale, between Maestra''s Post and the Fire Scar Shrine, lies a shrine dedicated to Aessina, a spirit of the wilderness. It is a quiet glade where night elf hunters train and buy their supplies, and where a spirit healer guides the fallen back to the living. Here dwells Therysil, sister of a wanderer named Therylune. The peace is uneasy. Felguards and felslayers from the Fire Scar Shrine to the south prowl near the edge of the glade.', 'warcraft.wiki.gg/wiki/Shrine_of_Aessina (dedicated to Aessina, a wilderness spirit); quest 945 description and reward text; zone_areas area 416: Therysil 3585, Alenndaar Lapidaar hunter trainer, Bolyun, Harlown Darkweave, Spirit Healer, Lesser Felguard, Felslayer; zone_npcs map coordinates: Maestra''s Post 26,38; shrine 22,52; Fire Scar Shrine 25,63'),
(33108, 1, 331, 8, 0, 0, 'Fire Scar Shrine', 'In southwestern Ashenvale lies the Fire Scar Shrine, a place of great evil where demons walk openly beneath the trees. Felslayers and lesser felguards hold the ground, and a demon called Akkrilus is sometimes found among them. Their master is Ilkrud Magthrull, a powerful orc warlock who makes his home here. The fel creatures do not keep to the shrine: a few prowl north as far as the edge of the Shrine of Aessina''s quiet glade.', 'quest 973 description (powerful orc warlock at the Fire Scar Shrine, a place of great evil in southwestern Ashenvale, little more than an annoyance); quest 1140 description (Ilkrud''s writings reveal the soul gems); creature_text 3664 (For the Dark Strand); zone_areas area 417: Felslayer, Lesser Felguard, Akkrilus 3773, Ilkrud Magthrull 3664'),
(33109, 1, 331, 9, 0, 0, 'Iris Lake', 'Iris Lake lies east of Astranaar along the road through central Ashenvale. On its isle rests Elune''s Tear, a stone found in no other place and said to wash away corruption. Shadethicket moss eaters wander its shores, with a rarely seen creature called Branch Snapper among them. A little beyond the lake, up a quiet path north of the road, the dryad Shael''dryn tends a moonwell. She refuses to leave the forest or give it up to corruption.', 'quest 1033 description (Elune''s Tear, isle on Iris Lake east of Astranaar); quest 1024 description (moonwell east of Iris Lake, turn north off the road); quest 1026 description (Shael''dryn knew of the treants, now corrupted); page_text 411 (Shael''dryn protects the moonwell, refuses to leave the forest); zone_areas area 424: Shadethicket Moss Eater, Branch Snapper 10641, Elune''s Tear 19015; area 425 Moonwell: Shael''dryn 3916'),
(33110, 1, 331, 10, 0, 0, 'The Ruins of Stardust', 'South of Astranaar, near the mountains that divide Ashenvale from Stonetalon, the Ruins of Stardust stand in a lake, once a holy place of the night elves. A small fountain at the center of the lake still gives water so pure that shamans of the Horde seek it out for their rites. Bushes dusted with a frosted powder grow among the stones, and that stardust is said to cool a raging fever. The ruins are not undefended. Old tales warned that great creatures of nature guard them against visitors, and Shadethicket raincallers and wood shapers do indeed roam the water.', 'quest 1534 description and request text (holy place, fountain at the center of the lake, guarded by large creatures of nature); quest 1034 description (frosted dust may abate fever, ruins to the south); warcraft.wiki.gg/wiki/Ruins_of_Stardust (holy place, lake island); zone_areas area 418: Shadethicket Raincaller, Wood Shaper, Stardust Covered Bush'),
(33111, 1, 331, 11, 0, 0, 'Mystral Lake', 'Mystral Lake is the largest lake in Ashenvale, lying in the south of the forest not far from the tunnel of the Talondeep Path. Its waters have turned against all who come near: befouled water elementals rise from it, and one called Tideress bears a glowing globe of the filth within. On the northern shore a small Sentinel camp, the Silverwind Refuge, keeps trainers and merchants, and there Sentinel Velene Starstrike wants to learn who controls the elementals. The Horde has its eye on a gazebo on the lake that looks over the camp, and on the high ground to the southeast an old furbolg named Krolg lives alone.', 'warcraft.wiki.gg/wiki/Mystral_Lake (largest lake, south of Silverwind Refuge, Sarilus corrupted the elementals); quest 1056 description (Talondeep Path not far from Mystral Lake); quest 25 description (gazebo overlooking the Alliance outpost); quests 1016, 1017 (Velene Starstrike at Silverwind Refuge, Sarilus Foulborne); quest 1030 description (southeast of Mystral Lake); page_text 407 (Krolg above Lake Mystral); creature_loot: Tideress 12759 drops the Befouled Water Globe; zone_areas: Velene and trainers in area 420, Befouled Water Elemental, Eck''alom, Tideress, Krolg in 421'),
(33112, 1, 331, 12, 0, 0, 'Fallen Sky Lake', 'Fallen Sky Lake is a small lake in southeastern Ashenvale with an island at its heart. The night elves once came here to gather moonstones, fallen stones holding a power that could give back strength the body had lost. Then the Shadethickets came. Stone movers and bark rippers now roam the shore, and their leader, a Shadethicket Oracle, has gathered every fallen moonstone and hoards them on the island. He will give them up only in death.', 'quest 1035 description (moonstones gathered at Fallen Sky Lake to the southeast until the Shadethickets came; the Oracle hoards them); warcraft.wiki.gg/wiki/Fallen_Sky_Lake (small lake, island, Oracle on the island); zone_areas area 422: Shadethicket Stone Mover, Bark Ripper, Oracle 3931'),
(33113, 1, 331, 13, 0, 0, 'Raynewood Retreat', 'In the heart of Ashenvale, Raynewood Retreat surrounds a great tree of the same name. Cenarion protectors and vindicators, Sentinels and the dryads called laughing sisters guard its glades, while blink dragons flit through the branches. At the top of the tree, kept from prying eyes, dwells Keeper Ordanus, one of the eldest sons of the forest god Cenarius. Elsewhere in the retreat prowls the nightsaber Shadumbra, feared by every Horde traveler bound west for the Zoram Strand.', 'warcraft.wiki.gg/wiki/Raynewood_Retreat (great tree, Ordanus one of the eldest sons of Cenarius); quest 1088 description and request text (Ordanus at the top of a great tree named Raynewood, spirited away from the peak of Stonetalon); quest 1087 description (Braelyn''s master, Jaedenar); quest 1945 description (laughing sisters are dryads near Raynewood); quest 24 reward text (Shadumbra and trips west to the Zoram Strand); zone_areas area 426: Laughing Sister, Cenarion Protector, Cenarion Vindicator, Ashenvale Sentinel, Blink Dragon, Keeper Ordanus 4273, Shadumbra 12677; quest 1087 description (Braelyn: druids stifle the flow of magic; master in Jaedenar)'),
(33114, 1, 331, 14, 0, 0, 'The Howling Vale', 'In northern Ashenvale, near the Felwood border, a cave holds the ruined Shrine of Mel''Thandris, where an old inscription still asks Elune to shine upon the vale and light the ways of the forest forever. Wolf-men fill it now. Terrowulf fleshrippers and shadow weavers prowl the cave under a Packlord, and their chilling calls gave the vale its name. The shrine keeps the Tome of Mel''Thandris, a book that is no true book: its leaves were blessed by Mel''Thandris herself and record events of import.', 'quest 1022 description and texts (shrine of Mel''Thandris near the Felwood border overrun by wolf-men, tome blessed by Mel''Thandris, Scythe of Elune); page_text 395 (shrine inscription); page_text 401 (Velinde ordered the packs to remain at the Shrine of Mel''Thandris); warcraft.wiki.gg/wiki/Howling_Vale (cave, Terrowulf); zone_areas area 419: Terrowulf Fleshripper, Shadow Weaver, Packlord 3792, Ancient Inscription, Tome of Mel''Thandris'),
(33115, 1, 331, 15, 0, 0, 'Xavian', 'Xavian is a satyr stronghold in northeastern Ashenvale, west of Forest Song, raised among the ruins of an old night elf temple. Xavian felsworn, hellcallers, rogues and betrayers fill its camps, and they work their foul rites with oil seized from a Warsong delivery. The satyrs hold the Branch of Cenarius, a relic the dryads of the forest set out to win back, and the sisters who went searching for it among the ruins have not returned.', 'quest 1021 description (ruins of a night elf temple in Xavian to the northwest of Forest Song); quest 1031 description (Geltharis has the Branch); quest 6571 description (satyrs use the stolen oil for rituals in Night Run, Satyrnaar and Xavian); zone_areas area 429: Xavian Felsworn, Rogue, Hellcaller, Betrayer, Geltharis 4619, Anilia 3920, Warsong Oil'),
(33116, 1, 331, 16, 0, 0, 'Satyrnaar and Night Run', 'Bleakheart satyrs, tricksters, hellcallers and shadowstalkers hold Satyrnaar, camping among old night elf ruins with a satyr called Prince Raze, working their rites with oil seized from a Warsong delivery. To the west, Felmusk satyrs, rogues, felsworn and shadowstalkers hold Night Run. In each camp a soul gem glows among the satyrs'' stones, and neither tribe welcomes anyone who comes near.', 'quest 9519 description and reward text (Satyrnaar once a shrine, Chalice of Elune, pilgrims, still shines); quest 9517 (Satyrnaar fel wood); quest 1140 description (soul gems in Night Run and Satyrnaar, trapped Highborne souls, blood-soaked temples); warcraft.wiki.gg/wiki/Satyrnaar (Bleakheart satyr, allied with the cult); zone_areas area 430: Bleakheart satyrs, Prince Raze 10647, Tainted Wood, Blue Soulgem, Chalice of Elune; area 428: Felmusk satyrs, Red Soulgem'),
(33117, 1, 331, 17, 0, 0, 'Splintertree Post', 'Splintertree Post is the Horde''s chief outpost in Ashenvale, raised by Grom Hellscream''s Warsong clan when the orcs first came into the forest during the Third War. It stands in the east, north of the road from the Barrens, and Splintertree guards stand watch around it. Most of its people are orcs and tauren, though a goblin trader, Pixel, has stopped here on her way to Ratchet. Mastok Wrilehiss watches the caravans and dislikes everyone, Senani Thunderheart calls hunters to the Ashenvale Hunt, Locke Okarr keeps the lumber camps supplied, and Ertog Ragetusk sends raiders against Silverwing Outpost.', 'warcraft.wiki.gg/wiki/Splintertree_Post (founded by Grom and the Warsong during the Third War, orcs and tauren); quest 6382 description (outpost due north of the path from the Barrens); quest 9428 reward text (Advisor Sunsworn, cementing the relationship with the Horde); quest 6441 (Pixel heading to Ratchet); gossip Mastok Wrilehiss 12737; quests 6383, 6571, 6544; zone_areas area 431; CreatureDisplayInfo 12968 (Pixel is a female goblin)'),
(33118, 1, 331, 18, 0, 0, 'Silverwing Outpost', 'Silverwing Outpost is a Sentinel stronghold in the forest southwest of Splintertree Post, held by Silverwing sentinels and warriors under the command of Duriel Moonfire, a night elf with a fierce reputation. It stands uncomfortably close to the Horde. Ashenvale outrunners slip out from here to spy on the Horde''s defenses, and the orcs of Splintertree hunt them through the woods to keep the Alliance blind. The orcs plan worse. The Warsong raider Torek has gathered his warriors to storm the outpost and cut down its leader, hoping to win a few good scars in the fight.', 'quest 6503 description and reward text (outrunners from Silverwing Outpost gathering intelligence); quest 6544 description (Silverwing Outpost to the west, its leader Duriel Moonfire, defended by sentinels and warriors); creature_text 12858 (They say Duriel is a fierce night elf; good scars); warcraft.wiki.gg/wiki/Silverwing_Sentinels (Duriel Moonfire a leader); zone_areas area 2360: Silverwing Sentinel 12896, Silverwing Warrior 12897'),
(33119, 1, 331, 19, 0, 0, 'The Dor''Danil Barrow Den', 'South of Splintertree Post lies the Dor''Danil Barrow Den, long a resting place of night elf druids. The Horde''s advance left it behind enemy lines, and then the Forsaken came. They made a camp beside it to brew poisons and diseases in bottles, and within the barrows the druids no longer sleep. Severed sleepers, dreamers and keepers haunt the halls, restless and hostile, among them Taneel Darkwood, Uthil Mooncall and Mavoris Cloudsbreak, and rotting slimes devour whatever they find. Forsaken assassins and the Darkslayer Mordenthal still prowl the camp, and the hippogryph Sharptalon hunts the hills nearby.', 'warcraft.wiki.gg/wiki/Dor''Danil_Barrow_Den (resting place of druids, behind enemy lines, Forsaken severed the sleepers); quest 1011 description (Forsaken camp near the barrow den brewing diseases in bottles); quest 1012 description (druids poisoned and murdered, severed and driven mad); page_text 413 (rotting slimes devour almost anything); zone_areas area 432: Severed Sleeper, Dreamer, Keeper, the three druids, Rotting Slime, Forsaken Assassin, Darkslayer Mordenthal 3736, Sharptalon 12676, Bottle of Disease'),
(33120, 1, 331, 20, 0, 0, 'Warsong Lumber Camp', 'In eastern Ashenvale the Warsong clan fells the ancient trees on a scale the night elves can hardly bear to watch. Peons and Horde deforesters work the stands, shredders bought in Ratchet tear through the trunks, and grunts, shamans and scouts guard the cutting. A second Warsong labor camp to the southwest, near Fallen Sky Lake, does the same work. The Silverwing Sentinels count the logging a ruin of their forest and fight the Warsong over it, and the camps have other enemies too: satyrs and furbolgs have plundered their supplies.', 'quest 9518 description (Gorthak redoubles efforts, cutting more than they can use); quest 6504 description (shredder picked up from Ratchet for the lumber camp); quest 9534 description (demons raid the Warsong Lumber Camp); quest 6571 description (supplies stolen by furbolgs and satyrs); warcraft.wiki.gg/wiki/Fallen_Sky_Lake (west of the Warsong Labor Camp); zone_areas area 437: Warsong Peon, Horde Deforester, Warsong Shredder, Grunt, Shaman, Horde Scout, Overseer Gorthak 17304; area 3177 similar; posarea: Warsong Labor Camp peons around 1500,-2400 (southwest of the lumber camp, beside Fallen Sky Lake); gossip Sentinel Luciel Starwhisper 17287; quest 9518 (blight); quest 8372 description (Silverwing Sentinels at war with the Warsong Outriders over the destruction of the forest)'),
(33121, 1, 331, 21, 0, 0, 'Forest Song', 'Forest Song is an old night elf shrine and outpost in the Nightsong Woods of northeastern Ashenvale, a quiet glade where few keep watch. The druid Kayneth Stillwind gathers reports of a corruption he fears is moving through the forest, Sentinel Melyria Frostshadow carries on the work of holding the demons of Felwood back from Ashenvale, and the dryad Illiyana waits anxiously for word of her sisters. Satyrs hold the ruins to the west, the Warsong cut timber to the south, and demons roam the hills beyond.', 'warcraft.wiki.gg/wiki/Forest_Song (Kayneth once the only inhabitant, draenei under Nemos and Vedaar, Gnarl purifies the wood); quest 4581 description (shrine of Forest Song in the Nightsong Woods); gossip Kayneth Stillwind 3848, Architect Nemos 17291, Gnarl 17310, Sentinel Luciel Starwhisper 17287 (satyr to the west, orcs to the south, demons of Felfire Hill); quest 9517 description and reward text; gossip Sentinel Luciel Starwhisper 17287 (satyr to the west, orcs to the south, demons of Felfire Hill); quest 1022 description (Melyria holds the demons of Felwood back from Ashenvale); quest 1021 description (Illiyana); zone_areas area 2358: Kayneth 3848, Melyria 3880, Illiyana 3901'),
(33122, 1, 331, 22, 0, 0, 'Felfire Hill and Demon Fall Canyon', 'In Demon Fall Canyon, in southeastern Ashenvale, Grom Hellscream and Thrall faced the pit lord Mannoroth, who had first cursed the orcs with his blood. Grom struck the demon down and died in the blast of its death, and with Mannoroth gone the blood curse was ended. A monument raised by Thrall marks the place where Grom lies, and Mannoroth''s broken spear still floats above the canyon. Yet the Legion never wholly left. Searing infernals, felguards and mannoroc lashers roam Felfire Hill, the canyon and the ridge above it, and a demon called Diathorus the Seeker haunts the heights.', 'warcraft.wiki.gg/wiki/Demon_Fall_Canyon (Grom kills Mannoroth and dies in the explosion, monument); page_text 2211 (Monument to Grom Hellscream, signed by Thrall); page_text 2078 (Mannoroth first cursed the orcs; curse ended with his death); quest 9522 description (Gorgannon near Mannoroth''s floating broken spear, Diathorus atop Demon Fall Ridge, monument); quest 9526 description and reward text (seedlings on Felfire Hill); zone_areas areas 434, 435, 436: Searing Infernal, Roaming Felguard, Mannoroc Lasher, Gorgannon 17300, Monument 21004'),
(33123, 1, 331, 23, 0, 0, 'Bough Shadow', 'At the far northeastern edge of Ashenvale, just beyond Forest Song, a great tree shelters a portal into the Emerald Dream, one of four such gateways in the world; the others lie in Duskwood, the Hinterlands and Feralas. Green dragonkin stand guard over it: Emeraldon oracles walk with boughguards and tree warders, while the dragons Phantim and Dreamstalker keep close to the portal. None of them welcome visitors.', 'warcraft.wiki.gg/wiki/Bough_Shadow (just beyond Forest Song, portal to the Emerald Dream, Phantim, Dreamstalker, Emeraldon groups); creature_text 14887 (Ysondre); zone_areas area 438: Emeraldon Boughguard, Oracle, Tree Warder, Phantim 5314, Dreamstalker 12498, Ysondre 14887'),
(33124, 2, 331, 1, 1, 0, 'Raene Wolfrunner', 'Raene Wolfrunner is a Sentinel officer in Astranaar, never far from her wolf Dagri. She came from Darnassus by way of Auberdine to deal with the furbolgs of Ashenvale, and she knows these forests as though they were part of her, though they still hide much danger. Sentinel Selarin, who calls her mistress, sends recruits down from Darkshore, and old Thundris Windweaver of Auberdine sends help too. She sends hunters against the Thistlefur and Foulweald tribes, and she worries for her longtime friend Teronis, who went seeking an old wizard''s rod that might slow the furbolg attacks and has yet to return.', 'gossip Raene Wolfrunner 3691; quest 10752 description and reward text (came through Auberdine from Darnassus, saved Thundris); quest 990 description (Selarin: my mistress Raene Wolfrunner); quests 1054, 1025, 991, 1023; warcraft.wiki.gg/wiki/Raene_Wolfrunner (officer, wolf Dagri)'),
(33125, 2, 331, 2, 1, 0, 'Delgren the Purifier', 'Delgren the Purifier is a human paladin who has made his home among the night elves at Maestra''s Post, lending his strength wherever the Sentinels find demons or undead. The ways of the kaldorei were strange to him at first, he admits, but he has come to respect them greatly as allies. He has taught his pupil Balthule Shadowstrike much of the Light and the art of battle, and while Balthule watches the Tower of Althalaxx in Darkshore, Delgren deals with the Cult of the Dark Strand in Ashenvale, a thorn in his side that he means to remove.', 'quest 967 description and reward text (paladin, helps the Sentinels against demons and undead, grew to respect the night elves; taught Balthule); quest 1140 description (learned the orcs'' tongue though his order scoffed); page_text 443-444 (Athrikus''s journal: that infuriating paladin, believes us a minor threat, just another death cult); warcraft.wiki.gg/wiki/Delgren_the_Purifier (human paladin)'),
(33126, 2, 331, 3, 1, 0, 'Kayneth Stillwind', 'Kayneth Stillwind is a night elf druid of Forest Song. He fears that a corruption is moving through Ashenvale, and he gathers reports such as Shindrell Swiftfire''s to find its trail. He suspects the Forsaken, the undead arm of the Horde, who lurk among the ruins and barrows of his people, of meaning to spread disease through the night elves'' lands, and he wants a bottle taken from their camp near the Dor''Danil Barrow Den so that he can test it himself and learn its purpose.', 'quest 4581 description and reward text (Kayneth fears a corruption moving through Ashenvale); quests 1011, 1012 descriptions; creature_text 3848 (the disease attacks the mind, I must resist); quest 9519 description; gossip Kayneth Stillwind 3848; warcraft.wiki.gg/wiki/Kayneth_Stillwind (druid; once Forest Song''s only inhabitant)'),
(33127, 2, 331, 4, 1, 0, 'Krolg', 'Krolg is an old furbolg of the Foulweald tribe who lives alone on the high ground near Mystral Lake, one of the few of his kind untouched by the fel moss that has maddened the tribes. He was cast out of his tribe as the corruption took hold, and he blames the night elves for it, sure that their pride brought ruin on his people. Yet his hatred has limits. He wishes no harm on elven children, and he holds that the furbolgs must answer for their own evils, chief among them the power hungry Ran Bloodtooth. Only a visitor in furbolg shape could ever earn his trust.', 'quest 1030 description and reward text (furbolg safe from Fel Moss, blames the night elves, cast out of his tribe); quest 1045 description and reward text (does not wish ill upon their children, we must police our own, hope tribes meet in less violent times); page_text 407 (venerable furbolg of the Foulweald tribe above Lake Mystral)'),
(33128, 2, 331, 5, 1, 8, 'Vindicator Vedaar', 'Vindicator Vedaar of the Hand of Argus oversees, with Architect Nemos, the draenei who have come to Forest Song at the night elves'' invitation. He carries his people''s long memory of flight: the Burning Legion all but destroyed the draenei, and again and again they fell back before it, finding a new home only for the demons to come once more. In Ashenvale he means to stop running. The Legion''s remnant on Felfire Hill and in the Demon Fall country to the south is to him an evil that must be cleansed.', 'quest 9516 description (Legion all but destroyed our race, we retreated over and over, no more); quest 9520 reward text (By the Seven Crystals of Ata''mal); gossip Vindicator Vedaar 17303 (the evil to the south must be cleansed); creature_template 17303 subname Hand of Argus; warcraft.wiki.gg/wiki/Forest_Song'),
(33129, 2, 331, 6, 1, 0, 'Talen', 'Talen is a night elf drawn by the drowned city of Zoram. He was skimming over its sunken ruins in his small boat when naga surged from the water and set upon him, and he fled ashore with what supplies he could carry, losing his most prized possession on the way: an ancient statuette, the very reason he had braved the Zoram Strand. He believes the old city holds many secrets, and that the statuette may be the key to many of them.', 'quest 1007 description and reward text; quest 1009 description and request text (Ring of Zoram, rulers of the city, opens any lock, Ruuzel); creature_text 3846 (statuette must hold a hidden compartment; it''s locked); warcraft.wiki.gg/wiki/Talen (night elf); CreatureDisplayInfo 4173 (Talen is a male night elf)'),
(33130, 2, 331, 7, 2, 0, 'Senani Thunderheart', 'Senani Thunderheart is a tauren hunter of Splintertree Post who welcomes young newcomers to what she calls a new frontier, a land full of chances for them to prove their mettle. To her the call of the hunt is something heard from deep within, and it comes from deep within every one of us, if only we listen closely. She keeps the Ashenvale Hunt, a trial against three legendary beasts of the forest, hoping that those who take it up will learn something about themselves along the way. She greets each trophy with praise and promises that songs of the hunters'' deeds will be sung at campfires and lumber mills across Ashenvale.', 'gossip Senani Thunderheart 12696; quest 235, 742, 6382 reward text (new frontier, chances to prove mettle); quest 6383 reward text (learn something about yourself); quest 2 reward text (songs at campfires and lumber mills); warcraft.wiki.gg/wiki/Senani_Thunderheart (female tauren hunter)'),
(33131, 2, 331, 8, 2, 0, 'Je''neu Sancrea', 'Je''neu Sancrea is a troll shaman of the Earthen Ring at Zoram''gar Outpost, a student of the elements so absorbed in reading the waves that he sometimes fails to notice the people around him. The elements, he teaches, share knowledge that must be learned and secrets that must be kept. He watches the nearby depths of Blackfathom, where the naga harvest crystals of great elemental power and the Twilight''s Hammer has moved into the ruins of an old moonshrine, and he fears the cult means to turn the elements against the Horde.', 'gossip Je''neu Sancrea 12736; quest 824 request text and reward text (does not notice people; globe is a device that feeds elementals, tainted); quest 6922 reward text (Baron Aquanis likely corrupted by the Twilight''s Hammer); quests 6563, 6921, 6565; warcraft.wiki.gg/wiki/Je''neu_Sancrea (jungle troll shaman, Earthen Ring); quest 6922 reward text (Baron Aquanis); quest 6563 description (naga harvesting the crystals); quest 6921 description (Twilight''s Hammer in the Moonshrine Ruins)'),
(33132, 2, 331, 9, 2, 0, 'Karang Amakkar', 'Karang Amakkar of Zoram''gar Outpost greets every arrival to what he calls the front lines of the Horde''s conquest of Ashenvale. He thinks in routes and gaps. Thistlefur Village blocks a path between Zoram''gar and Splintertree Post that would let the Horde go around Astranaar altogether, so he sends warriors to thin the furbolgs there. Against the Foulweald tribe southeast of Astranaar he plans a show of force: his banner planted on their totem mound and held until their chief, Murgut, comes out to save face for the tribe.', 'gossip Karang Amakkar 12757; quest 216 description and reward text (path that circumvents Astranaar, conquest in full swing); quest 6621 description and reward text (banner on the Foulweald totem mound, Chief Murgut, not to be trifled with)'),
(33133, 2, 331, 10, 0, 0, 'Ilkrud Magthrull', 'Ilkrud Magthrull is an orc warlock who makes the Fire Scar Shrine of southwestern Ashenvale his home, among the felguards and felslayers of that evil place. A summoned succubus attends him, and he greets intruders with a war cry: a shout for the Dark Strand, or a threat to take their heads, or to cut their throats and bleed them dry. He fights with shadow bolts, and when hard pressed he calls up guardians to stand beside him.', 'quest 973 description (powerful orc warlock at Fire Scar Shrine, little more than an annoyance); quest 1140 description (Ilkrud''s scribblings reveal the soul gems); creature_text 3664; page_text 443 (orcs and trolls easiest, their hatred of the Alliance); mod-individual-progression zone_ashenvale.sql smart_scripts 3664 (Summon Succubus, Shadow Bolt, Ilkrud''s Guardians)'),
(33134, 3, 331, 1, 1, 0, 'Raene''s Cleansing', 'The furbolgs of Ashenvale were not always enemies of the night elves, but times have changed, and their attacks on Raene Wolfrunner''s people grow bolder. Her longtime friend Teronis, who also aids the Sentinels, believed he had found a way to slow them: a rod created by a now dead, evil wizard. Before he left Astranaar he spoke of seeking a gem for the rod, said to be hidden at the shrine in Lake Falathim at the base of the mountain to the west, which had since been overrun. He has yet to return, and Raene asks for someone to find him.', 'quests 991, 1023, 1024, 1026, 1027, 1028, 1055, 1029, 1030, 1045, 1046 descriptions and reward texts; page_text 403-414 (Teronis'' journal: Dartol, the three parts, Lake Falathim shrine, treants near Felwood, Dor''danil druids, Krolg); creature_text 3916 (Shael''dryn rebuilds the rod)'),
(33135, 3, 331, 2, 1, 0, 'A Cure for Relara', 'In Astranaar a child named Relara Whitemoon has fallen gravely ill, and the herbalist Orendil Broadleaf of Maestra''s Post senses that her sickness is more than one of the body. Her health grows weaker by the hour. Orendil means to treat her with Bathran''s Hair, a plant that once grew in the old ruins of Bathran''s Haunt to the north, just south of the Darkshore border, and was known to cure ailments of the spirit, and he asks for it to be gathered for him.', 'quests 1010, 1020, 1033, 1034, 1035 descriptions and reward texts; creature_text 3847 (Orendil mixes the hair), 3892 (Relara wakes, asks for stew, wants to play), 3894 (Pelturas places the tear in stew, poultice, crushes moonstones into tea, weeps with joy)'),
(33136, 3, 331, 3, 1, 0, 'The Soul Gems of Athrikus', 'When Balthule Shadowstrike''s warning about the Cult of the Dark Strand reached Maestra''s Post, Delgren the Purifier already knew the cult as a thorn in his side, for he had been fighting its members at the Ruins of Ordil''Aran, northeast of the post. One of them, he says, carries a soul gem that he believes holds the secret of the cult''s power, and he is sure that with it in his hands he can decipher what the cult keeps hidden. He asks for it to be taken from them and brought to him.', 'quests 970, 973, 1140, 1167, 981 descriptions and reward texts; creature_text 3663 (breaking the soulstone; Tell me, spirit, where might we find the other soulgems)'),
(33137, 3, 331, 4, 1, 0, 'The Branch of Cenarius', 'The dryad Illiyana of Forest Song is frantic. Her sisters went to take the Branch of Cenarius back from the satyrs, searching for the ruins of a night elf temple at Xavian to the northwest. They promised to be back soon, but two whole days have gone by without a word. Anilia, who was leading the search, is the one Illiyana most wants found, and she begs any stranger who will listen to go to Xavian and look for her and the others.', 'quests 1021, 1031, 1032 descriptions, request and reward texts'),
(33138, 3, 331, 5, 1, 0, 'The Scythe of Elune', 'Sentinel Melyria Frostshadow of Forest Song has given much effort to driving the remaining demons from Felwood to the north, with few successes, though she has kept most of the demonic presence out of Ashenvale. Now a new mystery has arisen near the Felwood border. The ruined Shrine of Mel''Thandris has been overtaken by mysterious wolf-men, whose chilling calls have given the place its name, the Howling Vale. At the shrine lies the Tome of Mel''Thandris, which records events of import, and Melyria hopes it will shed light on why the wolf-men have come.', 'quests 1022, 1037, 1038, 1039, 1040, 1041 descriptions and reward texts; page_text 396-402 (Velinde''s Journal); quest 1041 description (Ruzzgot: parted on the way north, bound for Darkshire)'),
(33139, 3, 331, 6, 2, 0, 'The Ashenvale Hunt', 'Heralds in Orgrimmar and Thunder Bluff, and the hunter Jorn Skyseer in the Barrens, send young warriors north to Splintertree Post, where Senani Thunderheart keeps the Ashenvale Hunt. Three legendary beasts make up the hunt, each a test of cunning and might, and those who take it up may need aid to bring them down: the great bear Ursangous, who roams near the Talondeep Path; the nightsaber Shadumbra, who stalks Raynewood Retreat; and the hippogryph Sharptalon, who hunts the hills by the Dor''Danil Barrow Den. Senani asks only for proof of each deed, hoping the hunters will learn something about themselves along the way.', 'quests 235, 742, 6382 descriptions (lead-ins from Warcaller Gorlach, Bluff Runner Windstrider, Jorn Skyseer); quest 6383 reward text (the three creatures); quests 23, 24, 2 descriptions and reward texts; quest 247 reward text; zone_areas: Ursangous in area 1276, Shadumbra in 426, Sharptalon in 432'),
(33140, 3, 331, 7, 2, 0, 'The Befouled Waters', 'The caravans between Splintertree Post and Stonetalon have come to a standstill, for Mystral Lake has come alive and its water elementals attack anyone who comes near, which means anyone on the way to the Talondeep Path. Mastok Wrilehiss, who has little love for anyone, wants the elementals put down. He wants something more useful still: the gazebo on the lake that looks straight over the Alliance camp scouted, since from there the Horde might quietly keep an eye on its enemies.', 'quest 25 description and reward text; quest 1918 description and reward text (item-started from the Befouled Water Globe, dropped by Tideress); quest 824 description and reward text; gossip Mastok Wrilehiss 12737'),
(33141, 3, 331, 8, 0, 0, 'The Warsong Lumber Camp', 'Nowhere is the struggle for Ashenvale plainer than at the Warsong Lumber Camp, where the orcs fell the ancient trees of the eastern forest. The Silverwing Sentinels are at war with the Warsong over the destruction, while the Horde holds that the night elves would deny it one of its largest sources of lumber. At Splintertree Post the camp''s troubles fall to Locke Okarr. He scrambles to keep it supplied with saw blades from Ratchet, axes from Booty Bay, rope stolen by furbolgs and oil seized by satyrs for their rituals, and Gurda Ragescar hunts for the wind-scattered pages of a shredder manual, unable to get back to work without them.', 'quest 9518 description and reward text; quest 9517 description and reward text; quest 9521 description and reward text (Sentinel Farsong at Silverwing Grove directs the efforts); quest 6571 description; quest 6581 request text (Pixel, saw blades from Ratchet); quest 6504 description; quest 6504 description (Gurda Ragescar); quest 8372 description (Silverwing Sentinels at war with the Warsong Outriders over the forest); quest 8368 description (the Alliance would deny the Horde one of its largest sources of lumber)'),
(33142, 3, 331, 9, 0, 8, 'The Dreadlords of Demon Fall', 'The demons of Felfire Hill, Demon Fall Canyon and Demon Fall Ridge are a remnant of a force that invaded the world long ago, and both sides of Ashenvale''s war have reason to hate them. At Forest Song, Vindicator Vedaar of the Hand of Argus vows that his people will retreat from the Legion no more. At Splintertree Post the orc Valusha wants the same thing for her own reasons: the demons have been raiding the Warsong Lumber Camp, and they make worthy foes. Each sends fighters against the infernals, felguards and mannoroc lashers.', 'quests 9516, 9520, 9522 (Alliance) and 9534, 9535, 9536 (Horde) descriptions and reward texts; warcraft.wiki.gg/wiki/Valusha (orc)'),
(33143, 3, 331, 10, 0, 0, 'The Deeps of Blackfathom', 'Near the northern end of the Zoram Strand lies Blackfathom Deeps, long ago a great temple of Elune that held a powerful moonwell. Rumors run through Kalimdor that the Twilight''s Hammer has joined the naga there. The Argent Dawn in Darnassus wages war on the cult and has had no report for weeks from Thaelrid, the scout it sent to watch them. In Auberdine, Gershala Nightwhisper wants brain stems from its satyrs and naga, fearing the blood elves are headed for the same deformity. The Horde has come too. Je''neu Sancrea of the Earthen Ring wants to know why the naga harvest the sapphire clusters in its tunnels, and seeks a fathom core holding the record of elemental activity in the ruins the cult has taken.', 'quests 1198, 1199, 1200 descriptions and texts (Argent Dawn, temple of Elune, moonwell, Aku''Mai, Kelris); quest 1275 description (Gershala Nightwhisper); quests 6562, 6563, 6564, 6565, 6921 descriptions and reward texts; quest 6563 description (BFD along the Zoram Strand north of Zoram''gar)');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(33100, 1, 8, 255, 'In this age the forest has new guests. At the invitation of the kaldorei, draenei of the Hand of Argus are helping to restore the old outpost of Forest Song in the northeast, while blood elves, newly joined to the Horde, have sent an envoy to Splintertree Post to cement their place among its warriors.', 'quest 9533 description (draenei revitalizing an old night elf outpost with the kaldorei, under Nemos and Vedaar); quest 9428 reward text (Advisor Sunsworn: cement our relationship with the rest of the Horde)'),
(33101, 1, 0, 255, 'Kerlonian reached Maestra''s Post in the end, though the drowsy druid nodded off more than once on the long road down from Darkshore. Liladris was overjoyed that he had made it, and quite sure she would soon find him asleep somewhere about the camp.', 'quest 5321 description and reward text; creature_text 11218 (falls asleep along the way, sees Liladris)'),
(33101, 2, 0, 255, 'Aynasha survived her ambush. Guarded on the road until her antidote took hold, she went on to report to her superiors, and Sentinel Onaeya welcomed the news that she was alive and well, asking Elune to watch over the one who had saved her.', 'quest 5713 description and reward text; creature_text 11711 (the remedy is working, I must go report to my superiors)'),
(33106, 1, 0, 255, 'Vindicator Palanaar, a draenei paladin of the Light, waits in Astranaar for those of her people sent to aid the night elves as part of the draenei''s place in the Alliance. Emissary Valustraa sends word ahead of each, and Palanaar bids them ask among the townsfolk where help is needed.', 'quest 9432 description and reward text (AllowableRaces 1024, ends at Palanaar 17106)'),
(33106, 2, 8, 255, 'In this age the draenei stand beside the night elves, and the draenei paladin Vindicator Palanaar has come to Astranaar to be of help to them, sending willing hands east to her people''s new settlement at Forest Song.', 'npc_text 8802 (Palanaar gossip); quest 9533 description'),
(33107, 1, 0, 255, 'Therylune''s wanderings took her as far as the Master''s Glaive in Darkshore, where cultists surrounded her, and only with help did she slip away. Word of her safety reached the shrine afterward, and Therysil, astonished at how far her sister had strayed and how unwholesome a place she had found, thanked the messenger warmly.', 'quest 945 description and reward text; creature_text 3584'),
(33108, 1, 0, 255, 'Delgren the Purifier of Maestra''s Post long knew of Ilkrud and counted him little more than an annoyance, never troubling to deal with him. That changed when the hunt for the Cult of the Dark Strand, and a spirit freed from one of its soul gems, led straight to the warlock''s door.', 'quest 973 description; creature_text 3663 (Delgren questions the freed spirit)'),
(33109, 1, 0, 255, 'Shael''dryn knew Dartol''s rod and the treants who guarded part of it, or did once. The treants near the Felwood border have become corrupted, their nature twisted, and it upsets her deeply that she can do so little to help them.', 'quest 1026 description and request text'),
(33111, 1, 0, 255, 'Bracers taken from the elementals and read with a divining scroll name their maker. Velene knows him at once: Sarilus Foulborne, the only undead mage in the Barrens able to defile so many elementals and the only one foolish enough to try, likely laughing at her from the top of Dreadmist Peak.', 'quest 1016 reward text; quest 1017 description'),
(33111, 2, 0, 255, 'Krolg is no ordinary furbolg. He is a venerable elder of the Foulweald tribe whom the fel moss has spared, an outcast driven from his people as their corruption spread, and he keeps to the heights above the lake alone.', 'page_text 407 (Teronis'' Journal: venerable Foulweald furbolg above Lake Mystral); quest 1030 description and reward text'),
(33114, 1, 0, 255, 'The tome shows what it will, and no one truly understands why. Read for Sentinel Melyria Frostshadow, it gave up a vision tied to a name, the priestess Velinde Starsong, and to a thing she had been given, the Scythe of Elune. The Sentinels mean to look into it further.', 'quest 1022 reward text'),
(33114, 2, 0, 255, 'The wolf-men did not come here by chance. Velinde Starsong''s journal tells that when the worgen began to multiply beyond her control, she gathered as many of the packs as she could find and ordered them to remain at the Shrine of Mel''Thandris.', 'page_text 401 (Velinde''s Journal, item 5520)'),
(33115, 1, 0, 255, 'Near the ruins lay Anilia, who had led the dryads, dying of a wound in her side. With her last breath she gestured to the north, toward an archway, and gave the thief a name: the satyr Geltharis.', 'quest 1021 reward text; quest 1031 description'),
(33116, 1, 0, 255, 'The gems are no satyr work. Ilkrud Magthrull''s tome shows that the Cult of the Dark Strand hid its master Athrikus Narassin''s last two soul gems here, one in each camp, binding trapped Highborne souls within the satyrs'' blood-soaked temples.', 'quest 1140 description and objectives'),
(33116, 2, 8, 255, 'Satyrnaar was once a prominent shrine of the night elves. Its keepers held the Chalice of Elune, entrusted to them by the priests of the goddess, and pilgrims came to feel the healing power it was rumored to hold. The chalice lies among the ruins still, while the very wood of the place has been fouled by the satyrs'' corruption.', 'quest 9519 description; quest 9517 description (Satyrnaar fel wood); zone_areas area 430: Chalice of Elune 181681, Tainted Wood 181916'),
(33117, 1, 0, 255, 'Advisor Sunsworn of the blood elves keeps a place here, greeting those her ambassador sends ahead. Her people should help wherever they can, she tells them, to cement their bond with the rest of the Horde, and she points them deeper into the post and on to Zoram''gar on the far coast.', 'quest 9428 description and reward text (AllowableRaces 512, ends at Sunsworn 17100)'),
(33117, 2, 8, 255, 'In this age the blood elves are part of the Horde, and their advisor, Sunsworn, has a place at the post. The orc Valusha, too, now calls for fighters against the demons raiding the Warsong Lumber Camp.', 'quest 9534 description; creature 17100, 17355 spawns in area 431'),
(33119, 1, 0, 255, 'In time the barrows gave up their secret. Kayneth Stillwind of Forest Song tested one of the Forsaken''s bottles and learned what had happened here: the undead poisoned and murdered the sleeping druids, and the ghosts that roam the halls are their spirits, severed and maddened, their once great leaders among them.', 'quest 1012 description; creature_text 3848'),
(33120, 1, 8, 255, 'Of late the camp answers to Overseer Gorthak. The Sentinels of Forest Song, just to the north, strike at the logging often, and the Burning Legion''s remnant on Felfire Hill has begun to raid the camp as well.', 'quest 9518 description (Gorthak, a blight); quest 9534 description (demons raid the lumber camp); zone_areas area 437: Overseer Gorthak 17304'),
(33121, 1, 8, 255, 'The glade, all but forgotten for years, is waking. The kaldorei have invited the draenei to share in restoring Forest Song, and under Architect Nemos and Vindicator Vedaar of the Hand of Argus tents are rising where buildings will one day stand. Nemos will not fell the grove''s ancient trees, so the ancient Gnarl purifies timber taken from the Warsong loggers and from Satyrnaar. Sentinel Luciel Starwhisper watches against satyrs, orcs and demons, and Kayneth is glad to hear other voices in the glade again.', 'gossip Architect Nemos 17291 (npc_text 8873), Gnarl 17310 (9986), Sentinel Luciel Starwhisper 17287 (8874), Kayneth Stillwind 3848 (8875); quest 9517 description and reward text; quest 9533 description'),
(33122, 1, 8, 255, 'Another demon, Gorgannon, now keeps to the canyon near Mannoroth''s floating spear. At Forest Song the ancient Gnarl has saved seeds for just such a purpose, and he wants them planted in the hill''s fertile mounds to help take the land back from the demons.', 'quest 9522 description (Gorgannon near the spear); quest 9526 description and reward text; zone_areas area 435: Gorgannon 17300; area 434: Fertile Dirt Mound 181690'),
(33122, 2, 8, 255, 'Once the seedlings were planted, Gnarl told how it may take a great many years for them to grow into ancients, yet in the fullness of time they will stand with the night elves against the demons of Felfire Hill.', 'quest 9526 reward text'),
(33123, 1, 2, 255, 'Of late something more terrible has come through the portal. At times the great green dragon Ysondre herself emerges here, crying that the strands of life have been severed and calling on the Dreamers to come forth and take their vengeance.', 'creature_text 14887 (Ysondre); mod-individual-progression ipp_aware_npcs.sql and checkIPPhasing (14887 phased in at Bough Shadow from state 2)'),
(33124, 1, 0, 255, 'Raene takes Thundris''s help with some amusement. So the old elder still thinks she needs looking after? He seems to forget, she says, that it was she who pulled him from harm''s way, and she means to remind him who saved whom.', 'quest 10752 reward text'),
(33124, 2, 0, 255, 'Teronis did not live to finish his quest, but it was finished all the same. The skull of Ran Bloodtooth now rests in Astranaar beside Dartol''s rod, where all can see it, and Raene is certain her old friend would be proud.', 'quest 1046 reward text; gossip Raene Wolfrunner 3691 (npc_text 6555: you have completed Teronis'' mission)'),
(33125, 1, 0, 255, 'Delgren studies his enemies as closely as he fights them. Against the scoffing of others in his order he learned the orcish tongue, and it let him read the crude writings of the warlock Ilkrud Magthrull and learn where the cult''s master hid his last soul gems.', 'quest 1140 description'),
(33125, 2, 0, 255, 'Athrikus Narassin is dead, and a page of his journal shows what he made of Delgren: an infuriating paladin poking into the cult''s affairs in Ashenvale, who took the Dark Strand for a minor threat, just another death cult. Athrikus had known all along, too, that Balthule was spying on his tower.', 'Journal Page (item 5839, page_text 443-444), dropped by Athrikus Narassin 3660 in Darkshore; quest 981'),
(33126, 1, 0, 255, 'He tested the bottle himself. Its disease attacked his mind, but Kayneth resisted it, and in his struggle he saw a vision of the druids of Dor''Danil poisoned and murdered by the undead, torn from their bodies and driven mad. To give their spirits some hope of peace, he asked for their once great leaders to be destroyed.', 'quest 1012 description; creature_text 3848'),
(33126, 2, 0, 255, 'When the deed was done Kayneth felt the anguish of the barrows lessen. It was grim work, he said, for those spirits were only victims of the Forsaken''s evil, and he hoped that with their leaders gone the other maddened spirits would find peace.', 'quest 1012 reward text'),
(33126, 3, 8, 255, 'With the draenei now at Forest Song, Kayneth is glad to hear the voices of others again, for he had begun to fear he might be the last of the kaldorei to see these lands before their descent into corruption. He has also set his hopes on the Chalice of Elune, an old relic of the shrine now called Satyrnaar, hoping its power might rejuvenate the wounded forest.', 'gossip Kayneth Stillwind 3848 (npc_text 8875); quest 9519 description'),
(33126, 4, 8, 255, 'The Chalice of Elune was carried out of Satyrnaar and into Kayneth''s hands. A latent power lingers in it, he found, one that not even long exposure to the satyrs'' corruption could dim, and after all these years it still shines.', 'quest 9519 reward text'),
(33127, 1, 0, 255, 'With Ran Bloodtooth and his guards slain, Krolg allows that a small part has been done to return the tainted forest to its former glory. He would enjoy the company of his own kind again, he says, and he hopes their tribes may one day meet under less violent times.', 'quest 1045 reward text'),
(33128, 1, 0, 255, 'Then a parchment taken from a slain demon detailed preparations for an attack on Forest Song itself. By the Seven Crystals of Ata''mal, Vedaar swore it would never come to pass, crumpling the plans in his fist, and he sent his allies after the two dreadlords who command the demons.', 'quest 9520 description and reward text; quest 9522 description'),
(33128, 2, 0, 255, 'With Gorgannon and Diathorus the Seeker slain, the threat to Forest Song was lifted. Never again, Vedaar vows, will the Burning Legion threaten his people here, and he offers the deepest gratitude of the Hand of Argus for delivering them from a fight he believes they would very likely have lost.', 'quest 9522 reward text'),
(33129, 1, 0, 255, 'Found again, the statuette proved to hold a hidden compartment, and it was locked. Only the Ring of Zoram, which belonged to the city''s rulers before the Sundering drowned it and is said to open any lock within it, could open it, and the naga leader Ruuzel had found the ring first.', 'creature_text 3846; quest 1009 description and request text'),
(33129, 2, 0, 255, 'The Ring of Zoram was taken from Ruuzel''s isle on the northern edge of the drowned city and placed in Talen''s hands at last. Grateful beyond words, he swore that the deed would remain forever in his memory.', 'quest 1009 reward text'),
(33131, 1, 0, 255, 'Mastok Wrilehiss of Splintertree once sent him a befouled globe of water from Mystral Lake. Je''neu knew such devices as the means by which the more powerful elementals draw their energy, and one so tainted troubled him. The Earthen Ring, he resolved, would study it and try to end the corruption.', 'quest 824 reward text'),
(33131, 2, 0, 255, 'A strange water globe taken from Baron Aquanis, an elemental power in Blackfathom long thought corrupted, gives him the means to prove what corrupted it. It would surprise him little to learn it was the Twilight''s Hammer, and the globe should show how they did it.', 'quest 6922 reward text'),
(33132, 1, 0, 255, 'With the Thistlefur thinned, Karang counts on a path between the two outposts free of Alliance entanglements, though he means to keep sending forces against the furbolgs. The Horde''s conquest of Ashenvale, he declares, is now in full swing.', 'quest 216 reward text'),
(33132, 2, 0, 255, 'The banner held and Chief Murgut fell, his totem carried back to Zoram''gar. The challenge sends the Foulweald a strong message, Karang says: the Horde is not to be trifled with, and he expects little trouble from that tribe for a long time.', 'quest 6621 reward text'),
(33133, 1, 0, 255, 'To Delgren the Purifier of Maestra''s Post, the warlock had long been a nuisance not worth his time. When the trail of the Cult of the Dark Strand led to the Fire Scar Shrine, the paladin decided that Ilkrud''s time had come.', 'quest 973 description'),
(33133, 2, 0, 255, 'His tome, scrawled in Orcish, betrayed the cult. Delgren could read it, and it told him where Athrikus Narassin, master of the Dark Strand, had hidden his last two soul gems: with the satyrs, one at Night Run and one at Satyrnaar.', 'quest 1140 description'),
(33133, 3, 0, 255, 'Athrikus''s own journal, a page of which was found on his corpse, shows how such servants were won. Hatred, he wrote, bends people easily to one''s will, and the orcs and trolls were the easiest of all, their hatred of the Alliance making them willing listeners to the message of the Dark Strand.', 'page_text 443 (Journal Page, item 5839, dropped by Athrikus Narassin)'),
(33134, 1, 0, 255, 'Teronis was found dead atop the island shrine, cut down by murlocs. His journal survived. In it he told of Dartol, a human wizard who learned druidic magic and made a rod to move among the furbolgs in their own shape, until they caught him turning tribe against tribe, killed him and split the rod in three: a gem hidden at the lake, a shaft given to the treants near Felwood and a pommel left with the druids of Dor''Danil.', 'quest 991 reward text; quest 1023 description; page_text 403-414 (Teronis'' Journal, item 5505)'),
(33134, 2, 0, 255, 'Raene mourned and asked that his task be finished. The gem was won back from the murlocs, and the dryad Shael''dryn knew the rest: the shaft lay in a chest near the Felwood border whose key a corrupted treant carried, and the pommel lay among the barrows of the slain Dor''Danil druids. With all three pieces Shael''dryn rebuilt the rod, a simple design, she said, more druidic than arcane.', 'quests 1023, 1024, 1026, 1027 texts; creature_text 3916'),
(33134, 3, 0, 255, 'A hidden shrine in the hills about her glade restored the rod''s power. Raene could only guess at what Teronis had meant to do next: take the shape of a furbolg and speak with one still safe from the fel moss, perhaps somewhere southeast of Mystral Lake.', 'quest 1028 texts; quest 1030 description'),
(33134, 4, 0, 255, 'In furbolg form the rod''s bearer found Krolg, an old Foulweald outcast untouched by the corruption, who blamed the prideful night elves for his people''s ruin yet held that the furbolgs must police their own. He asked that Ran Bloodtooth, power hungry and made only stronger by the corruption, be slain.', 'quest 1030 reward text; quest 1045 description'),
(33134, 5, 0, 255, 'Ran Bloodtooth fell, and his skull, the trophy of the fiercest furbolg threat in Ashenvale, was carried to Astranaar. Raene set it beside Dartol''s Rod in a place of reverence for others to see. Teronis, she said, would be proud.', 'quest 1046 reward text'),
(33135, 1, 0, 255, 'The hair was gathered, though Orendil was troubled to hear that the Forsaken now walked at Bathran''s Haunt. He mixed his cure and sent it to Astranaar, to Relara''s father, Pelturas Whitemoon.', 'quest 1010 reward text; quest 1020 description; creature_text 3847'),
(33135, 2, 0, 255, 'Orendil''s cure slowed the illness but did not end it. Pelturas turned to the other remedies the herbalist had named should the first one fail, beginning with Elune''s Tear, a stone found only on the isle of Iris Lake and said to wash away corruption.', 'quest 1033 description'),
(33135, 3, 0, 255, 'Elune''s Tear, stirred into a stew, eased Relara''s nightmares, and frosted dust from the Ruins of Stardust, made into a poultice, broke her fever. Still she was very weak, and Pelturas believed only the power of a moonstone could give back her strength, though the Shadethicket Oracle of Fallen Sky Lake hoarded them all.', 'quests 1033, 1034 reward texts; quest 1035 description; creature_text 3894'),
(33135, 4, 0, 255, 'A moonstone was taken from the Oracle and crushed into a cup of tea. Relara woke, her eyes no longer heavy, asking to go out and play, and her father wept with joy and pressed his most dear possession on the one who had saved her.', 'quest 1035 reward text; creature_text 3892, 3894'),
(33136, 1, 0, 255, 'Broken open, the gem gave up a trapped spirit, and Delgren asked it where the cult''s other soul gems might be found. What he learned pointed to Ilkrud Magthrull, the orc warlock of the Fire Scar Shrine, and Delgren judged that the time had come to deal with him.', 'quest 970 reward text; creature_text 3663; quest 973 description'),
(33136, 2, 0, 255, 'Ilkrud fell, and Delgren, who had learned to read Orcish despite his order''s scorn, found in the warlock''s tome that the cult''s master, Athrikus Narassin, still kept two soul gems, hidden in the satyr camps of Night Run and Satyrnaar.', 'quest 973 reward text; quest 1140 description'),
(33136, 3, 0, 255, 'Freeing the Highborne souls bound in those gems broke much of Athrikus''s power. Delgren wondered whether the satyrs had been left in the forest too long, then urged that the moment be seized, and sent his champion north to Balthule for the final blow.', 'quest 1140 objectives and reward text; quest 1167 description'),
(33136, 4, 0, 255, 'Word came back to Maestra''s Post that Athrikus Narassin lay stilled and the Cult of the Dark Strand was beaten and scattered. Delgren had known the task would be met, and he gave his blessing, sensing great deeds still ahead for the one who had done it.', 'quest 981 description and reward text'),
(33137, 1, 0, 255, 'Anilia was found near the ruins with a gaping wound in her side. Drawing her rescuer close, she pointed toward an arch to the north and gasped out the name of the one who had taken the branch, Geltharis. Then she died.', 'quest 1021 reward text; quest 1031 description'),
(33137, 2, 0, 255, 'The satyr paid for the branch with his life, and it was carried back into dryad hands. Illiyana could scarcely believe the news of Anilia, for only the day before, she said, the two of them had been running and playing in the woods together.', 'quest 1031 reward text'),
(33137, 3, 0, 255, 'Struggling with a sorrow she hardly understood, Illiyana asked one thing more: the horns of the satyrs who had taken her sister from her. When they were brought to her she gave her thanks, sure that Anilia''s spirit was gladdened.', 'quest 1032 description and reward text'),
(33138, 1, 0, 255, 'The tome''s visions showed that the priestess Velinde Starsong had received something called the Scythe of Elune. Velinde was Melyria''s predecessor in Ashenvale: at first she seemed to have the demons of Felwood in hand, but little by little her efforts faltered, and one day she simply disappeared. Thyn''tel Bladeweaver of the Sentinels in Darnassus might know more.', 'quest 1022 reward text; quest 1037 description'),
(33138, 2, 0, 255, 'Velinde''s journal, kept with her belongings in Darnassus, told the rest. The scythe, a gnarled branch perhaps older than the kaldorei, weakened the barriers of time and space, and through it she reached the worgen and drew them into the world to fight the demons. At first they served her well. Then a pack vanished, and their numbers kept growing even when she summoned no more. Hearing whispers that a Kirin Tor wizard named Arugal had also called worgen, she set out to seek him.', 'page_text 396-402 (Velinde''s Journal, item 5520); quest 1038 texts'),
(33138, 3, 0, 255, 'Her trail ran across the sea. The wharfmaster of Ratchet found her in his ledgers, booked to Booty Bay on the Black Osprey, and the caravan driver Ruzzgot remembered the night elf priestess who had traveled with him until they parted on the road north. She was bound for Darkshire.', 'quests 1039, 1040, 1041 texts'),
(33138, 4, 0, 255, 'The answers lay in the mines of Duskwood, and they were carried back to Thyn''tel Bladeweaver. The high priestess would be disappointed, she said, for she and Velinde had been good friends, and it unsettled her that the Scythe of Elune, surely the goddess''s own boon, had fallen out of her servants'' hands.', 'quest 1044 description and reward text'),
(33139, 1, 0, 255, 'Ursangous fell, a bear credited with many kills. A small crescent emblem on his paw, Senani judged, was surely the mark of the night elves who had trained him, and she named the hunter''s victory a testament to will and resolve.', 'quest 23 description and reward text'),
(33139, 2, 0, 255, 'Shadumbra fell. The nightsaber''s savagery was well known at Splintertree, where every trip west toward the Zoram Strand, above all on foot, had been fraught with danger because of the cat. With its head brought in as a trophy, that danger abated.', 'quest 24 reward text'),
(33139, 3, 0, 255, 'Sharptalon fell. The hippogryph had long terrorized the peons travelling from the lumber camps to Splintertree Post, and Senani promised that songs of the hunter''s bravery would soon be heard at campfires and lumber mills across Ashenvale.', 'quest 2 reward text'),
(33139, 4, 0, 255, 'The one who brings down all three beasts is hailed as a true hunter, the blood of a hunter streaking through the veins, and Senani gives a gift to mark the mighty deeds done in Ashenvale for the Horde.', 'quest 247 reward text'),
(33140, 1, 0, 255, 'The lake was torn up like a dust devil through the Barrens, as Mastok heard it, and the transports between Splintertree and Stonetalon should have an easier time of it. The gazebo, too, might yet become an observation post for keeping an eye on the Alliance, if it can be kept quiet.', 'quest 25 reward text'),
(33140, 2, 0, 255, 'Among the slain elementals, Tideress left behind an intensely glowing globe of foul water. Mastok had no idea what to make of it, but it gave him a thought: the Earthen Ring, shamans who know more of old gods and ancient lore than most scholars ever will. He sent the globe on to Je''neu Sancrea at Zoram''gar.', 'quest 1918 description and reward text; quest 824 description; creature_loot: Tideress 12759 drops the Befouled Water Globe'),
(33140, 3, 0, 255, 'Je''neu found the globe deeply disturbing. Powerful elementals draw their strength through such devices, and to find one so tainted spoke of a corruption of the elements themselves. He promised to see it studied properly by the Earthen Ring, in hope of ending that corruption.', 'quest 824 reward text'),
(33141, 1, 8, 255, 'At Forest Song the camp looks very different. Sentinel Luciel Starwhisper calls it a blight: every time her people slow the logging, Overseer Gorthak drives his crews harder, and they now fell more wood than they can use and leave it to rot. She sends fighters against Gorthak and his shredders, deforesters and scouts.', 'quest 9518 description'),
(33141, 2, 8, 255, 'Architect Nemos, who builds for the draenei at Forest Song, refuses to cut the old trees of the grove. Instead the Warsong loggers are to be relieved of their surplus timber, and the ancient Gnarl will purify it for the builders'' use.', 'quest 9517 description and reward text'),
(33141, 3, 8, 255, 'Forest Song does not fight alone. At Silverwing Grove, near the Barrens border, Sentinel Farsong directs the wider Sentinel effort against those who would destroy the forest, and Luciel''s reports from the northern front go to her.', 'quest 9521 description'),
(33142, 1, 0, 255, 'From the slain came parchments detailing preparations for a demonic attack on the very camp that had sent the hunters, and naming the two infamous dreadlords who control the demons: Gorgannon, in the canyon near Mannoroth''s floating, broken spear, and Diathorus the Seeker, in a barrow den atop the ridge. Without them, the demons below would be all but mindless.', 'quests 9520, 9535 descriptions; quests 9522, 9536 descriptions'),
(33142, 2, 0, 255, 'Gorgannon and Diathorus the Seeker were slain, and with them died the attack they had been preparing. The one who had sent the hunters after them swore that never again would the Burning Legion have its way here.', 'quests 9522, 9536 reward texts'),
(33143, 1, 0, 255, 'Thaelrid was found weakened within the deeps, with word of a wicked plot. Long ago, he said, the corruption of an Old God seeped up from beneath the earth and tainted the sacred moonwell, and Aku''Mai, servant of the Old God, rose from its waters. The cultists who occupy the temple with the naga are led by Twilight Lord Kelris, who sacrifices innocents to Aku''Mai for power.', 'quest 1198 reward text; quest 1200 description'),
(33143, 2, 0, 255, 'Kelris was slain and his head carried to Dawnwatcher Selgorm in Darnassus. He had eluded the Argent Dawn for a long time, and wherever evil made itself known in those parts he seemed to have had a hand; some had thought him dead or missing. His end spared many innocent lives.', 'quest 1200 reward text'),
(33143, 3, 0, 255, 'A damp note found in the deeps spelled out a plan. The naga priestesses were to bring the crystals to its writer, whose aquamancers would draw on the water spirits within them; with that power the cult would appease Aku''Mai, and one day bring him back and return the world to the rule of the Old Gods. Je''neu put a name to the writer: Lorgus Jett.', 'quest 6564 description and reward text; quest 6565 description'),
(33143, 4, 0, 255, 'Lorgus Jett was slain in Blackfathom Deeps. The Twilight''s Hammer was not stopped altogether, Je''neu admitted, but another of its plans to return the Old Gods to power had been staved off, and for now there was reason to rest easy.', 'quest 6565 reward text');
